"""Labels for shipments."""


def label_shipments(names, shipments):
    """Return (lookup, lines): a name -> weight dict and one 'name: weight' line per shipment."""
    pairs = zip(names, (x.weight for x in shipments))
    lookup = dict(pairs)
    lines = ["%s: %s" % (name, value) for name, value in pairs]
    return lookup, lines


def name_list(names):
    """Return the names joined by commas."""
    return ", ".join(names)


def group_by_route(shipments):
    """Return a dict from route to the list of shipments with that route."""
    groups = {}
    for x in shipments:
        groups.setdefault(x.route, []).append(x)
    return groups


def describe_shipment(shipment):
    """Return a one-line description of a shipment."""
    return "%s: %s" % (shipment.route, shipment.weight)

